ork Firewall Devel- oper Guide . RuleOrder -&gt; (string) Indicates how to manage the order of the rule evaluation for the rule group. DEFAULT_ACTION_ORDER is the default behavior. Stateful rules are provided to the rule engine as Suricata compatible strings, and Suricata evaluates them based on cer- tain settings. For more information, see Evaluation order for stateful rules in the Network Firewall Developer Guide . Possible values: o DEFAULT_ACTION_ORDER o STRICT_ORDER JSON Syntax: { "RuleVariables": { "IPSets": {"string": { "Definition": ["string", ...] } ...}, "PortSets": {"string": { "Definition": ["string", ...] } ...} }, "ReferenceSets": { "IPSetReferences": {"string": { "ReferenceArn": "string" } ...} }, "RulesSource": { "RulesString": "string", "RulesSourceList": { "Targets": ["string", ...], "TargetTypes": ["TLS_SNI"|"HTTP_HOST", ...], "GeneratedRulesType": "ALLOWLIST"|"DENYLIST"|"REJECTLIST"|"ALERTLIST" }, "StatefulRules": [ { "Action": "PASS"|"DROP"|"ALERT"|"REJECT", "Header": { "Protocol": "IP"|"TCP"|"UDP"|"ICMP"|"HTTP"|"FTP"|"TLS"|"SMB"|"DNS"|"DCERPC"|"SSH"|"SMTP"|"IMAP"|"MSN"|"KRB5"|"IKEV2"|"TFTP"|"NTP"|"DHCP"|"HTTP2"|"QUIC", "Source": "string", "SourcePort": "string", "Direction": "FORWARD"|"ANY", "Destination": "string", "DestinationPort": "string" }, "RuleOptions": [ { "Keyword": "string", "Settings": ["string", ...] } ... ] } ... ], "StatelessRulesAndCustomActions": { "StatelessRules": [ { "RuleDefinition": { "MatchAttributes": { "Sources": [ { "AddressDefinition": "string" } ... ], "Destinations": [ { "AddressDefinition": "string" } ... ], "SourcePorts": [ { "FromPort": integer, "ToPort": integer } ... ], "DestinationPorts": [ { "FromPort": integer, "ToPort": integer } ... ], "Protocols": [integer, ...], "TCPFlags": [ { "Flags": ["FIN"|"SYN"|"RST"|"PSH"|"ACK"|"URG"|"ECE"|"CWR", ...], "Masks": ["FIN"|"SYN"|"RST"|"PSH"|"ACK"|"URG"|"ECE"|"CWR", ...] } ... ] }, "Actions": ["string", ...] }, "Priority": integer } ... ], "CustomActions": [ { "ActionName": "string", "ActionDefinition": { "PublishMetricAction": { "Dimensions": [ { "Value": "string" } ... ] } } } ... ] } }, "StatefulRuleOptions": { "RuleOrder": "DEFAULT_ACTION_ORDER"|"STRICT_ORDER" } }
    /// </summary>
    [CliOption("--rule-group")]
    public string? RuleGroup { get; set; }

    /// <summary>
    /// A string containing stateful rule group rules specifications in Suricata flat format, with one rule per line. Use this to import your existing Suricata compatible rule groups. NOTE: You must provide either this rules setting or a populated Rule- Group setting, but not both. You can provide your rule group specification in Suricata flat for- mat through this setting when you create or update your rule group. The call response returns a RuleGroup object that Network Firewall has populated from your string. Constraints: o min: 0 o max: 2000000
    /// </summary>
