    /// <summary>
    /// A description of the rule group. Constraints: o max: 512 o pattern: ^.*$
    /// </summary>
    [CliOption("--description")]
    public string? Description { get; set; }

    /// <summary>
    /// The key:value pairs to associate with the resource. Constraints: o min: 1 o max: 200 (structure) A key:value pair associated with an Amazon Web Services re- source. The key:value pair can be anything you define. Typi- cally, the tag key represents a category (such as "environment") and the tag value represents a specific value within that cate- gory (such as "test," "development," or "production"). You can add up to 50 tags to each Amazon Web Services resource. Key -&gt; (string) [required] The part of the key:value pair that defines a tag. You can use a tag key to describe a category of information, such as "customer." Tag keys are case-sensitive. Constraints: o min: 1 o max: 128 o pattern: ^.*$ Value -&gt; (string) [required] The part of the key:value pair that defines a tag. You can use a tag value to describe a specific value within a cate- gory, such as "companyA" or "companyB." Tag values are case-sensitive. Constraints: o min: 0 o max: 256 o pattern: ^.*$ Shorthand Syntax: Key=string,Value=string ... JSON Syntax: [ { "Key": "string", "Value": "string" } ... ]
    /// </summary>
    [CliOption("--tags", GroupValues = true)]
    public IEnumerable<string>? Tags { get; set; }

    /// <summary>
    /// Indicates whether you want Network Firewall to just check the valid- ity of the request, rather than run the request. If set to TRUE , Network Firewall checks whether the request can run successfully, but doesn't actually make the requested changes. The call returns the value that the request would return if you ran it with dry run set to FALSE , but doesn't make additions or changes to your resources. This option allows you to make sure that you have the required permissions to run the request and that your request parameters are valid. If set to FALSE , Network Firewall makes the requested changes to your resources.
    /// </summary>
    [CliFlag("--dry-run", NegatedName = "--no-dry-run")]
    public bool? DryRun { get; set; }

    /// <summary>
    /// A complex type that contains settings for encryption of your rule group resources. KeyId -&gt; (string) The ID of the Amazon Web Services Key Management Service (KMS) customer managed key. You can use any of the key identifiers that KMS supports, unless you're using a key that's managed by another account. If you're using a key managed by another ac- count, then specify the key ARN. For more information, see Key ID in the Amazon Web Services KMS Developer Guide . Constraints: o min: 1 o max: 2048 o pattern: .*\S.* Type -&gt; (string) [required] The type of Amazon Web Services KMS key to use for encryption of your Network Firewall resources. Possible values: o CUSTOMER_KMS o AWS_OWNED_KMS_KEY Shorthand Syntax: KeyId=string,Type=string JSON Syntax: { "KeyId": "string", "Type": "CUSTOMER_KMS"|"AWS_OWNED_KMS_KEY" }
    /// </summary>
    [CliOption("--encryption-configuration")]
    public string? EncryptionConfiguration { get; set; }

    /// <summary>
    /// A complex type that contains metadata about the rule group that your own rule group is copied from. You can use the metadata to keep track of updates made to the originating rule group. SourceArn -&gt; (string) The Amazon Resource Name (ARN) of the rule group that your own rule group is copied from. Constraints: o min: 1 o max: 256 o pattern: ^arn:aws.* SourceUpdateToken -&gt; (string) The update token of the Amazon Web Services managed rule group that your own rule group is copied from. To determine the update token for the managed rule group, call DescribeRuleGroup . Constraints: o min: 1 o max: 1024 o pattern: ^([0-9a-f]{8})-([0-9a-f]{4}-){3}([0-9a-f]{12})$ Shorthand Syntax: SourceArn=string,SourceUpdateToken=string JSON Syntax: { "SourceArn": "string", "SourceUpdateToken": "string" }
    /// </summary>
    [CliOption("--source-metadata")]
