    /// <summary>
    /// Indicates whether you want Network Firewall to analyze the stateless rules in the rule group for rule behavior such as asymmetric rout- ing. If set to TRUE , Network Firewall runs the analysis and then creates the rule group for you. To run the stateless rule group ana- lyzer without creating the rule group, set DryRun to TRUE .
    /// </summary>
    [CliFlag("--analyze-rule-group", NegatedName = "--no-analyze-rule-group")]
