    /// <summary>
    /// An object that contains a RuleOptions array of strings. You use RuleOptions to determine which of the following RuleSummary values are returned in response to DescribeRuleGroupSummary . o Metadata - returns o Msg o SID RuleOptions -&gt; (list) Specifies the selected rule options returned by DescribeRule- GroupSummary . (string) Possible values: o SID o MSG o METADATA Shorthand Syntax: RuleOptions=string,string JSON Syntax: { "RuleOptions": ["SID"|"MSG"|"METADATA", ...] }
    /// </summary>
    [CliOption("--summary-configuration")]
